bool gt_EvacFirstEntry_Func (bool testConds, bool runActions) {
    // Automatic Variable Declarations
    // Conditions
    if (testConds) {
        if (!((UnitGetOwner(EventUnit()) == 1))) {
            return false;
        }

        if (!((gv_evacCompleted == false))) {
            return false;
        }
    }

    // Actions
    if (!runActions) {
        return true;
    }

    gv_evacCompleted = true;
    ObjectiveSetState(gv_evacObjective, c_objectiveStateCompleted);
    gv_evacCount = (gv_evacCount + 1);
    return true;
}

//--------------------------------------------------------------------------------------------------
void gt_EvacFirstEntry_Init () {
    gt_EvacFirstEntry = TriggerCreate("gt_EvacFirstEntry_Func");
    TriggerAddEventUnitRegion(gt_EvacFirstEntry, null, RegionFromId(97), true);
}

